Translate("ptBR", "azshara", {
	title = "Azshara",
	sections = {
		{
			title = "Resumo",
			text = [=[Azshara é uma terra de bosques vermelhos de outono, penhascos partidos e ruínas submersas na costa nordeste de {link:kalimdor}Kalimdor{/link}, a leste do {link:ashenvale}Vale Gris{/link} e ao sul de {link:winterspring}Hibérnia{/link}. Ela leva o nome da {link:queen-azshara}Rainha Azshara{/link} e carrega sua memória como uma ferida. Templos despedaçados se inclinam sobre a {link:bay-of-storms}Baía das Tempestades{/link}, as colunas de antigas cidades jazem meio afundadas na arrebentação, e os espíritos dos {link:high-elves}Bem-nascidos{/link} ainda vagam entre as pedras. Poucos vêm aqui por vontade própria. Os que vêm, vêm pelo que as ruínas ainda escondem.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra o ano em que os Bem-nascidos construíram pela primeira vez nestas praias. O que se sabe é que, na era anterior à {link:great-sundering}Grande Cisão{/link}, esta era uma terra de suas cidades e templos, e que seus maiores magos escreveram as leis do arcano em tabuletas e runas para que todos lessem. Quando o {link:well-of-eternity}Poço da Eternidade{/link} foi destruído no fim da {link:war-of-the-ancients}Guerra dos Antigos{/link}, a terra foi dilacerada. Grande parte da cidade de {link:ruins-of-eldarath}Eldarath{/link} caiu no mar, e a costa tornou-se a coisa recortada que é hoje. A rainha e seus servos se perderam sob as ondas. Os elfos noturnos que sobreviveram deram as costas a este lugar, e há dez mil anos o evitam.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Azshara não pertence a ninguém, e todos querem algo dela. Os {link:naga}nagas{/link} Spitelash saíram de novo do mar para reivindicar as ruínas de seus ancestrais. {link:satyrs}Sátiros{/link} {link:haldarr-encampment}Haldarr{/link} e Legashi assombram os bosques. Uma companhia de elfos sangrentos sob a maga {link:magus-rimtori}Rimtori{/link} acampou nos penhascos do norte para cavar em busca de tesouros dos Bem-nascidos. A {link:horde}Horda{/link} mantém um pequeno posto ensanguentado em {link:valormok}Valormok{/link}, e as {link:sentinels}Sentinelas{/link} vigiam do {link:talrendis-point}Campo Talrendis{/link}, na fronteira do {link:ashenvale}Vale Gris{/link}. Um arquimago humano mantém uma torre nas colinas do oeste, um caçador de demônios vive numa ilha da baía, e um dragão azul guarda os bosques do sul. No norte, atrás de um grande portão que nenhum forasteiro atravessou, pelursos lutam contra uma corrupção que sobe das profundezas.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os nagas Spitelash.{/b} Dominam as {link:ruins-of-eldarath}Ruínas de Eldarath{/link}, as praias e os recifes, e seu senhor da guerra governa a partir do {link:temple-of-zin-malor}Templo de Zin-Malor{/link}.
• {b}Os sátiros.{/b} O clã {link:haldarr-encampment}Haldarr{/link} espreita perto de {link:valormok}Valormok{/link}, e os Legashi dominam os bosques do norte.
• {b}Os elfos sangrentos.{/b} Agrimensores e recuperadores servem à {link:magus-rimtori}Maga Rimtori{/link}, que caça as relíquias dos Bem-nascidos.
• {b}Os pelursos do norte.{/b} Guardam o portão de {link:blackmaw-hold}Blackmaw Hold{/link} e não deixam nenhum estranho se aproximar.
• {b}Os gigantes dos penhascos.{/b} Vagam pelas colinas do sul e comem a própria pedra da terra.
• {b}A Revoada {link:the-drag}Drag{/link}ônica Azul.{/b} {link:azuregos}Azuregos{/link} e os dragonetes vigiam a antiga magia da costa.
• {b}Os makrura.{/b} O povo-caranguejo do {link:temple-of-arkkoran}Templo de Arkkoran{/link} adora seu senhor, {link:lord-arkkoroc}Lorde Arkkoroc{/link}.
• {b}Os mortos inquietos.{/b} Aparições dos Bem-nascidos assombram os santuários do oeste, presas ao arcano que amavam.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Era dos Bem-nascidos.{/b} {link:ruins-of-eldarath}Eldarath{/link} floresceu, e seus magos dedicaram a vida ao estudo do {link:arcane-magic}arcano{/link}.
• {b}A {link:great-sundering}Cisão{/link}.{/b} O Poço implodiu, a terra se partiu, e o mar engoliu metade de Eldarath.
• {b}O Longo Silêncio.{/b} Por dez mil anos as ruínas ficaram entregues a espíritos, feras e marés.
• {b}Os Dias de Hoje.{/b} Os nagas voltaram das profundezas. Caçadores de tesouros de todas as raças os seguiram.]=],
		},
		{
			title = "Saber da Costa",
			text = [=[• Os gigantes dos penhascos do sul devoram rocha e ruína igualmente. O que passa por eles endurece em azsharita, um cristal ao mesmo tempo flexível e muito resistente.
• Os elfos sangrentos chamam um goblin que já trabalhou para eles de "{link:kim-jael}Kim'jael{/link}". Ele jura que significa "ratinho", e não os perdoou.
• As tabuletas de {link:ruins-of-eldarath}Eldarath{/link} levam os nomes de quatro magos Bem-nascidos: Beth'{link:moon-priestess-amara}Amara{/link}, Jin'yael, Markri e Sael'hai.]=],
		},
	},
})

Translate("ptBR", "talrendis-point", {
	title = "Campo Talrendis",
	sections = {
		{
			title = "Resumo",
			text = [=[O Campo Talrendis é o posto das {link:sentinels}Sentinelas{/link} no oeste de {link:azshara}Azshara{/link}, perto da fronteira do {link:ashenvale}Vale Gris{/link}. É pequeno e vigilante. Um mestre de hipogrifos mantém aberta pelo céu a única estrada de volta para casa, e a arqueira Brinna {link:valanaar}Valanaar{/link} conserta os arcos das Sentinelas. As Sentinelas aqui vigiam a {link:horde}Horda{/link} em {link:valormok}Valormok{/link}, os sátiros nas colinas e os espíritos dos santuários do oeste. Um servo da Mãe Terra, {link:loh-atu}Loh'atu{/link}, acampa entre elas e jurou ajudar os elfos a purificar a terra tanto dos sátiros quanto dos mortos Bem-nascidos.]=],
		},
	},
})

Translate("ptBR", "valormok", {
	title = "Valormok",
	sections = {
		{
			title = "Resumo",
			text = [=[Valormok é o acampamento da {link:horde}Horda{/link} no oeste de {link:azshara}Azshara{/link}, ao norte do {link:haldarr-encampment}Assentamento Haldarr{/link}. É um posto solitário, com um mestre de mantícoras, um ferreiro e um cozinheiro. Um dia teve uma dúzia de guerreiros. A maioria deles seguiu a elfa sangrenta {link:magus-rimtori}Rimtori{/link} para as terras selvagens por ordem de Belgrom Rockmaul, de {link:orgrimmar}Orgrimmar{/link}, e ela os matou. {link:ag-tor-bloodfist}Ag'tor Bloodfist{/link}, que ficou, quer vingança. {link:jediga}Jediga{/link}, que foi mandada para cá como castigo, quer lucro. Nenhum dos dois espera ajuda de Orgrimmar. Suas mantícoras são o único caminho rápido da Horda para sair de Azshara.]=],
		},
	},
})

Translate("ptBR", "ruins-of-eldarath", {
	title = "Ruínas de Eldarath",
	aliases = { "Eldarath" },
	sections = {
		{
			title = "Resumo",
			text = [=[Eldarath era uma cidade dos Bem-nascidos nos penhascos acima da {link:bay-of-storms}Baía das Tempestades{/link}. Quando o mundo se partiu, grande parte dela caiu no mar. O que resta de pé é um labirinto de pedra pálida e arcos quebrados, dominado pelos nagas Spitelash. Quatro grandes tabuletas ainda se erguem entre as ruínas, cada uma com o nome de um mago Bem-nascido, e estudiosos de {link:ironforge}Altaforja{/link} à {link:undercity}Cidade Baixa{/link} querem cópias delas. As poças de maré ao longo de sua praia estão conspurcadas. Um {link:tauren}tauren{/link} que bebeu de uma adoeceu, e os boticários dos {link:forsaken}Renegados{/link} tomaram um interesse malsão pela água.]=],
		},
	},
})

Translate("ptBR", "temple-of-zin-malor", {
	title = "Templo de Zin-Malor",
	aliases = { "Zin-Malor" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Templo de Zin-Malor ergue-se no coração das {link:ruins-of-eldarath}Ruínas de Eldarath{/link}. Um dia ele guardou um cristal capaz de conter e comandar grandes forças arcanas. Os que o roubaram tinham más intenções, e o cristal se despedaçou. Seus guardiões tornaram-se espíritos amaldiçoados, e os escritos sagrados dos Bem-nascidos foram deixados a apodrecer nos salões do templo. Hoje o senhor da guerra {link:naga}naga{/link} {link:warlord-krellian}Krellian{/link} ocupa o templo como sua sede, atrás de uma muralha de guardas, e reúne toda magia que consegue encontrar. Os nagas o guardam com mais ferocidade do que qualquer outra parte das ruínas.]=],
		},
	},
})

Translate("ptBR", "bay-of-storms", {
	title = "Baía das Tempestades",
	sections = {
		{
			title = "Resumo",
			text = [=[A Baía das Tempestades é um golfo largo e cinzento que morde o meio de {link:azshara}Azshara{/link}. Suas águas são inquietas, e suas ilhas são poucas. Na margem norte fica o Ninho de {link:hetaera}Hetaera{/link}, o covil de uma fera de três cabeças que se diz a soberana destes mares. Os makrura de {link:temple-of-arkkoran}Arkkoran{/link} caçam em suas águas orientais, e os nagas nadam sob tudo isso. Numa pequena ilha ao sul, guardada por três canídeos vis, vive o caçador de demônios {link:loramus-thalipedes}Loramus Thalipedes{/link}.]=],
		},
	},
})

Translate("ptBR", "temple-of-arkkoran", {
	title = "Templo de Arkkoran",
	aliases = { "Arkkoran" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Templo de Arkkoran ergue-se à beira da água, no leste de {link:azshara}Azshara{/link}. É o lar dos makrura, o povo-caranguejo da costa, e do ser imenso a quem servem: {link:lord-arkkoroc}Lorde Arkkoroc{/link}, a quem até o caçador de demônios {link:loramus-thalipedes}Loramus{/link} chama de deus menor. Seus oráculos, estaladores e pinçadores guardam a aproximação e atacam qualquer estranho que encontram. Os que chegam vivos até ele podem negociar, mas ele sempre fixa um preço, e o último preço que cobrou foi pago em sangue.]=],
		},
	},
})

Translate("ptBR", "thalassian-base-camp", {
	title = "Base Darnassiana",
	sections = {
		{
			title = "Resumo",
			text = [=[Nos penhascos da península do norte, uma companhia de elfos sangrentos montou acampamento. Seus agrimensores e recuperadores vasculham a terra atrás dos tesouros perdidos dos Bem-nascidos, e moem a magia que encontram até virar um pó cintilante. Sua líder é a {link:magus-rimtori}Maga Rimtori{/link}. Ela contratou orcs e um goblin para ajudá-la, e traiu a ambos. Perto de suas próprias tendas há um círculo de cristais arcanos, disposto segundo o padrão de um antigo livro de invocação.]=],
		},
	},
})

Translate("ptBR", "legashi-encampment", {
	title = "Assentamento Legashi",
	aliases = { "Assentamento Legash", "Legashi Stronghold" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os sátiros Legashi dominam os bosques do norte de {link:azshara}Azshara{/link}, a leste de Ursolan e ao norte do acampamento dos elfos sangrentos. Seus invoca-infernos e ladinos servem ao Mestre Feardred. Numa colina acima deles, um goblin teimoso chamado {link:kim-jael}Kim'jael{/link} mantém um acampamento próprio e não parece temê-los. De todos os sátiros de Azshara, os Legashi são os mais numerosos. Viajantes dizem que uma fortaleza deles surgiu recentemente ali perto, embora ninguém saiba dizer o que ela abriga.]=],
		},
	},
})

Translate("ptBR", "haldarr-encampment", {
	title = "Assentamento Haldarr",
	aliases = { "Haldarr" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Assentamento Haldarr fica no sudoeste de {link:azshara}Azshara{/link}, perto do acampamento da {link:horde}Horda{/link} em {link:valormok}Valormok{/link}. É o covil do clã Haldarr de {link:satyrs}sátiros{/link}: trapaceiros, juramentados vis e brutamontes que um dia foram elfos. Eles profanam os bosques por onde {link:cenarius}Cenarius{/link} um dia andou. {link:loh-atu}Loh'atu{/link}, do {link:talrendis-point}Campo Talrendis{/link}, jurou à Mãe Terra ajudar a expulsá-los, e paga aos que voltam vivos de seu acampamento.]=],
		},
	},
})

Translate("ptBR", "shadowsong-shrine", {
	title = "Ermida Cantonegro",
	sections = {
		{
			title = "Resumo",
			text = [=[A Ermida Cantonegro é uma ruína no oeste de {link:azshara}Azshara{/link}, a nordeste do {link:talrendis-point}Campo Talrendis{/link}. É assombrada. Aparições e liches menores dos Bem-nascidos vagam entre suas pedras, ainda famintos pela magia arcana que os arruinou. Os espíritos perturbam todos os povos igualmente, e dizem que uma fome como a deles atrai o olhar da {link:burning-legion}Legião Ardente{/link}. As {link:sentinels}Sentinelas{/link} pediram que eles sejam libertados do mundo. Ali perto vagueia um fantasma mais sombrio, que leva o nome do capitão da {link:queen-azshara}Rainha Azshara{/link}.]=],
		},
	},
})

Translate("ptBR", "ravencrest-monument", {
	title = "Monumento a Cristacorvo",
	sections = {
		{
			title = "Resumo",
			text = [=[Nos penhascos da ponta sul de {link:azshara}Azshara{/link}, acima do mar aberto, jazem os restos de uma estátua colossal dos antigos elfos. Só as pernas continuam de pé. O resto jaz quebrado à volta delas, ou caiu nas ondas. Ela leva o nome da casa Cristacorvo, mas nenhuma crônica registra a quem ela honrava ou quando foi erguida. Os nagas Spitelash agora vagam entre os pedaços. Só se chega a ela por terra, por uma ponte.]=],
		},
	},
})

Translate("ptBR", "southridge-beach", {
	title = "Praia do Recife Sul",
	sections = {
		{
			title = "Resumo",
			text = [=[A Praia do Recife Sul fica na costa sul de {link:azshara}Azshara{/link}, abaixo das florestas onde o dragão azul {link:azuregos}Azuregos{/link} mantém sua vigília. Aqui o navio {i}Horizon Scout{/i} veio em busca de um ancoradouro seguro, sob o comando da {link:captain-vanessa-beltis}Capitã Vanessa Beltis{/link}. O sol não tinha se posto havia uma hora quando os nagas caíram sobre sua tripulação. Os sobreviventes resistiram num vale acima da praia, e ainda esperam ali, sabendo que os nagas voltarão. Alguns de seus passageiros vieram a Azshara por negócios próprios.]=],
		},
	},
})

Translate("ptBR", "blackmaw-hold", {
	title = "Blackmaw Hold",
	sections = {
		{
			title = "Resumo",
			text = [=[No norte de {link:azshara}Azshara{/link} ergue-se um grande portão dos pelursos. Desde que qualquer um em {link:kalimdor}Kalimdor{/link} se lembra, ele está fechado, e seus guardas expulsaram todo estranho que se aproximou. Atrás dele fica Blackmaw Hold, uma vasta cidade de pelursos escavada fundo na montanha. Seu povo luta contra uma corrupção que começou a se agitar em suas profundezas. Dizem que seus túneis descem ainda mais, até lugares mais antigos que a própria cidade.]=],
		},
	},
})

Translate("ptBR", "loramus-thalipedes", {
	title = "Loramus Thalipedes",
	subtitle = "O Caçador de Demônios de Azshara",
	found = "Uma pequena ilha no sul da Baía das Tempestades",
	hint = [=[Procure nas ilhas da Baía das Tempestades aquele que caça demônios.]=],
	allegiance = "Nenhuma, além de sua própria caçada",
	aliases = { "Loramus" },
	sections = {
		{
			title = "Resumo",
			text = [=[Loramus Thalipedes é um caçador de demônios que vive sozinho numa ilha da {link:bay-of-storms}Baía das Tempestades{/link}. Três canídeos vis o guardam: Raytaf, Shahiar e Zaman. Ele não tem paciência para interrupções. Ainda assim, sabe mais sobre os senhores da {link:burning-legion}Legião Ardente{/link} neste mundo do que qualquer sábio dos reinos, e ajudará qualquer um tolo o bastante para caçá-los.]=],
		},
		{
			title = "Importância",
			text = [=[Loramus é o único que sabe como ferir {link:razelikh-the-defiler}Razelikh, o Profanador{/link}. Conhece a história da retirada de {link:lord-kazzak}Lorde Kazzak{/link} para {link:the-tainted-scar}o Rasgo Infecto{/link}, o pacto que une os três capitães de Razelikh e o rito pelo qual se pode descobrir o nome verdadeiro do Profanador. Sem ele, a guerra contra o senhor demoníaco da {link:blasted-lands}Barreira do Inferno{/link} nem sequer poderia ser travada.]=],
		},
		{
			title = "Feitos",
			text = [=[• Realiza um ritual de iluminação para descobrir como a proteção de {link:razelikh-the-defiler}Razelikh{/link} pode ser quebrada.
• Envia buscadores a {link:lord-arkkoroc}Lorde Arkkoroc{/link} para comprar o nome verdadeiro do demônio.
• Prepara azsharita temperada para o ferreiro {link:galvan-the-ancient}Galvan{/link}, o Ancião, o único capaz de forjá-la.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica registra quem Loramus era antes de começar sua caçada, há quanto tempo vive em sua ilha, ou como veio a conhecer {link:galvan-the-ancient}Galvan{/link}.]=],
		},
	},
	chapters = {
		{
			title = "A História do Profanador",
			hint = "Sente-se e ouça a história do caçador de demônios.",
			text = [=[Os enviados pelo {link:fallen-hero-of-the-horde}Herói Caído da Horda{/link} encontram Loramus pouco acolhedor. Ele conta sua história mesmo assim, e não gosta de ser interrompido. Quando a Legião foi derrotada, {link:lord-kazzak}Kazzak{/link} foi rechaçado para {link:the-tainted-scar}o Rasgo Infecto{/link}, e {link:razelikh-the-defiler}Razelikh{/link}, o mais temido de seus tenentes, foi enviado para manter a terra por ele. Os ogros e os cultistas vieram para o seu lado, assim como os três que agora guardam seu amuleto.]=],
		},
		{
			title = "O Nome da Fera",
			hint = [=[Descubra o nome verdadeiro do demônio com o senhor dos makrura.]=],
			text = [=[Só uma arma que traga o nome verdadeiro de um demônio pode ferir a ele e a todos que o servem. Loramus não conseguiu descobrir esse nome sozinho. Enviou seu ajudante ao {link:temple-of-arkkoran}Templo de Arkkoran{/link}, e o preço do senhor dos makrura foi sangue. O nome voltou junto com uma têmpera drenada das cabeças de uma fera: {link:razelikh-the-defiler}Rakh'likh{/link}.]=],
		},
		{
			title = "Flagelo-vil",
			hint = [=[Leve a remessa do caçador de demônios ao ferreiro da Mithril Order.]=],
			text = [=[Com a azsharita das colinas do sul e a têmpera de {link:lord-arkkoroc}Arkkoroc{/link}, os materiais estavam prontos. Loramus os enviou para o sul, a {link:galvan-the-ancient}Galvan{/link}, o Ancião, na {link:stranglethorn-vale}Selva do Espinhaço{/link}. O velho ferreiro não ouvia o nome do caçador de demônios havia muitos anos.]=],
		},
	},
	mentions = {
		{ text = "O Caçador de Demônios" },
		{ text = "Loramus" },
		{ text = "Quebrando a Proteção" },
		{ text = "O Nome da Fera" },
		{ text = "Azsharita" },
		{ text = "A Formação do {link:scourge}Flagelo{/link}-vil" },
	},
	bonds = {
		{ id = "razelikh-the-defiler", name = "Razelikh, o Profanador", note = "o demônio que ele caça" },
		{ id = "lord-kazzak", name = "Lorde Kazzak", note = "o senhor do Profanador" },
		{ id = "lord-arkkoroc", name = "Lorde Arkkoroc", note = "conhece o nome verdadeiro" },
		{ id = "galvan-the-ancient", name = "Galvan, o Ancião", note = "um velho conhecido" },
		{ id = "fallen-hero-of-the-horde", name = "Herói Caído da Horda", note = "envia-lhe caçadores" },
	},
})

Translate("ptBR", "archmage-xylem", {
	title = "Arquimago Xylem",
	subtitle = "Senhor da Torre nas Colinas",
	found = "Sua torre nos penhascos acima do oeste de Azshara",
	hint = [=[Encontre o arquimago cuja torre domina Azshara. Seu servo espera lá embaixo.]=],
	allegiance = "Seus próprios estudos",
	aliases = { "Xylem" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Arquimago Xylem é um mago humano que fez seu lar numa torre no alto das colinas acima de {link:azshara}Azshara{/link}. Os visitantes precisam primeiro encontrar seu servo {link:sanath-lim-yo}Sanath Lim-yo{/link}, que os envia até a torre por magia. Xylem é orgulhoso, frio e muito poderoso. Ele é humano, como diz {link:jediga}Jediga{/link} de {link:valormok}Valormok{/link}, mas age como nenhum humano que ela já conheceu.]=],
		},
		{
			title = "Importância",
			text = [=[Xylem veio a {link:azshara}Azshara{/link} pelo mesmo motivo que todos os outros: sua magia. Compra o conhecimento dos Bem-nascidos, colhe o coral encantado da baía e vigia a terra por meio de feitiços de vidência. Até o senhor dos ladinos, {link:lord-jorach-ravenholdt}Jorach Ravenholdt{/link}, recorre a ele quando é preciso quebrar um encantamento.]=],
		},
		{
			title = "Feitos",
