	subtitle = "Capitã do Horizon Scout",
	found = "Um vale acima da Praia do Recife Sul",
	hint = [=[Encontre a capitã do navio que resiste acima da praia do sul.]=],
	allegiance = "Tripulação do Horizon Scout",
	aliases = { "Vanessa Beltis" },
	sections = {
		{
			title = "Resumo",
			text = [=[Vanessa Beltis é a capitã do {i}Horizon Scout{/i}. Ela trouxe seu navio para perto da costa sul de {link:azshara}Azshara{/link} em busca de um ancoradouro seguro. Uma hora depois do pôr do sol, os nagas atacaram. Procuravam algo e não encontraram, então voltaram.]=],
		},
		{
			title = "Importância",
			text = [=[Sua resistência mostra o que espera qualquer viajante honesto nas costas de {link:azshara}Azshara{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Mantém unidos sua tripulação e seus passageiros contra os nagas.]=],
		},
	},
	chapters = {
		{
			title = "Uma Tripulação sob Fogo",
			hint = "Fique ao lado da capitã contra os nagas.",
			text = [=[Os nagas vieram em ondas. Quando acabou, a capitã estava viva, mas muitos de sua tripulação não.]=],
		},
	},
	mentions = {
		{ text = "Uma Tripulação sob Fogo" },
	},
	bonds = {
		{ id = "azuregos", name = "Azuregos", note = "guarda os bosques acima de sua praia" },
	},
})

Translate("ptBR", "ogtinc", {
	title = "Ogtinc",
	subtitle = "Eremita dos Penhascos de Eldarath",
	found = "No alto dos penhascos a nordeste das Ruínas de Eldarath",
	hint = [=[Suba os penhascos a nordeste de Eldarath para encontrar o velho caçador.]=],
	allegiance = "Os velhos costumes da caça",
	sections = {
		{
			title = "Resumo",
			text = [=[Ogtinc vive sozinho nos penhascos acima de {link:ruins-of-eldarath}Eldarath{/link}. Já foi caçador, e ainda ensina os velhos costumes aos que o procuram. Suas lições são caçadas: o corcel casco-de-musgo, o açoita-ondas da costa e, por fim, o draco verde {link:morphaz}Morphaz{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[Ogtinc ensina que todo troféu traz uma lição, e que a maior presa deve ser caçada em companhia.]=],
		},
		{
			title = "Feitos",
			text = [=[• Envia caçadores atrás de galhadas perfeitas de corcel e de escamas de açoita-ondas.
• Envia-os atrás de {link:morphaz}Morphaz{/link}, no templo submerso.]=],
		},
	},
	mentions = {
		{ text = "Galhadas de Corcel" },
		{ text = "Açoitando Ondas" },
		{ text = "O Draco Verde" },
		{ text = "Dos Corcéis Nós Sabemos" },
	},
	bonds = {
		{ id = "morphaz", name = "Morphaz", note = "sua última lição" },
	},
})

Translate("ptBR", "varo-then-s-ghost", {
	title = "Fantasma de Varo'then",
	subtitle = "Sombra do Capitão da Rainha",
	found = "As terras assombradas do oeste de Azshara",
	hint = [=[Enfrente o fantasma que assombra o oeste e leva o nome do capitão da rainha.]=],
	allegiance = "Os mortos Bem-nascidos",
	sections = {
		{
			title = "Resumo",
			text = [=[Um fantasma vagueia pelas terras do oeste de {link:azshara}Azshara{/link} levando o nome de Varo'then. Na {link:war-of-the-ancients}Guerra dos Antigos{/link}, o Capitão Varo'then liderava a guarda da {link:queen-azshara}Rainha Azshara{/link}. O que resta dele ainda anda pela terra onde ela um dia governou. Ele não está sozinho. Aparições e liches menores dos Bem-nascidos assombram os santuários próximos, ainda famintos pela magia que os condenou.]=],
		},
		{
			title = "Importância",
			text = [=[O fantasma é um lembrete de que o passado de {link:azshara}Azshara{/link} não terminou. De todos os mortos Bem-nascidos destas terras, nenhum leva um nome mais famoso.]=],
		},
		{
			title = "Feitos",
			text = [=[• Assombra o oeste de {link:azshara}Azshara{/link}, além do alcance das {link:sentinels}Sentinelas{/link}.]=],
		},
	},
	bonds = {
		{ id = "queen-azshara", name = "Rainha Azshara", note = "a rainha a quem ele serviu" },
		{ id = "loh-atu", name = "Loh'atu", note = "liberta os mortos Bem-nascidos" },
	},
})

Translate("ptBR", "warlord-krellian", {
	title = "Senhor da Guerra Krellian",
	subtitle = "Senhor da Guerra dos Spitelash",
	found = "O Templo de Zin-Malor",
	hint = [=[Encontre o senhor da guerra naga que se esconde atrás de seus guardas no Templo de Zin-Malor.]=],
	allegiance = "Nagas Spitelash",
	aliases = { "Krellian" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Senhor da Guerra Krellian governa os nagas Spitelash de {link:ruins-of-eldarath}Eldarath{/link} a partir do {link:temple-of-zin-malor}Templo de Zin-Malor{/link}. Ele se mantém atrás de seus guardas e cobiça magia, sobretudo uma concha prismática que o {link:archmage-xylem}Arquimago Xylem{/link} também deseja.]=],
		},
		{
			title = "Importância",
			text = [=[Krellian é o senhor dos nagas que retomaram as ruínas de seus ancestrais. Os Spitelash despojam a baía de seu coral encantado e guardam as runas de {link:ruins-of-eldarath}Eldarath{/link}. O {link:archmage-xylem}Arquimago Xylem{/link} observou Krellian por meio de sua vidência, mas diz que não pode deixar sua torre para enfrentar o senhor da guerra pessoalmente.]=],
		},
		{
			title = "Feitos",
			text = [=[• Domina o {link:temple-of-zin-malor}Templo de Zin-Malor{/link}.
• Guarda uma concha prismática de estranho poder.]=],
		},
	},
	mentions = {
		{ text = "Senhor da Guerra Krellian" },
	},
	bonds = {
		{ id = "archmage-xylem", name = "Arquimago Xylem", note = "quer a concha dele" },
	},
})

Translate("ptBR", "gatekeeper-rageroar", {
	title = "Guardião do Portão Rageroar",
	subtitle = "Sentinela do Portão dos Pelursos",
	found = "Diante do portão de Blackmaw Hold",
	hint = [=[Aproxime-se do grande portão dos pelursos no norte de Azshara.]=],
	allegiance = "Pelursos do norte",
	aliases = { "Rageroar" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Guardião do Portão Rageroar guarda o grande portão no norte de {link:azshara}Azshara{/link}. Ele e seus guerreiros o mantiveram fechado contra todo forasteiro. O que eles guardam atrás dele, poucos além do portão chegaram a ver.]=],
		},
		{
			title = "Importância",
			text = [=[Rageroar está onde a velha {link:azshara}Azshara{/link} termina e começa o mistério de {link:blackmaw-hold}Blackmaw Hold{/link}. Seus guerreiros, batedores e xamãs guardam os acessos com ele. O que quer que perturbe a cidade atrás dele, os pelursos do portão não pediram ajuda a forasteiros.]=],
		},
		{ title = "Feitos", text = "• Bloqueia a entrada da cidade dos pelursos." },
	},
	bonds = {
		{ id = "blackmaw-hold", name = "Blackmaw Hold", note = "a cidade que ele guarda" },
	},
})
